import yaml, json
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_8/projects/acr-vla-conformal-refinement/registry.yaml') as f:
    data = yaml.safe_load(f)
# Check structure
if isinstance(data, dict):
    exps = data.get('experiments', {})
    if isinstance(exps, dict):
        for k, v in exps.items():
            if 'default-seed48' in k:
                print(json.dumps({k: v}, indent=2, default=str))
    elif isinstance(exps, list):
        for e in exps:
            if isinstance(e, dict) and 'default-seed48' in e.get('exp_id', ''):
                print(json.dumps(e, indent=2, default=str))
else:
    print('top-level type:', type(data))
"
